 FrameworkElement LiveHero(int seat,bool own){var p=match.Players[seat];var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(minimal?15:28)});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(minimal?9:14)});var boxes=new Grid();boxes.ColumnDefinitions.Add(new ColumnDefinition());boxes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1.4,GridUnitType.Star)});boxes.ColumnDefinitions.Add(new ColumnDefinition());
  string weapon=p.WeaponDurability>0?(minimal?"武":match.Card(p.WeaponId).Name+" "+match.WeaponAttackValue(seat)+"/"+p.WeaponDurability):(minimal?"武":"武器 · 空");var w=MatchBox(weapon,()=>{if(own&&p.WeaponDurability>0){BeginHeroAttack();}else if(p.WeaponId!=null)InspectMatchCard(match.Card(p.WeaponId));});boxes.Children.Add(w);
