  var resources=new Grid();resources.ColumnDefinitions.Add(new ColumnDefinition());resources.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var resourceText=T(p.Mana+" / "+p.MaxMana+(p.LockedMana>0?" · 锁"+p.LockedMana:"")+(!own?" · 手牌 "+p.HandCount:""),9,Muted);if(!own)enemyHandStatus=resourceText;resources.Children.Add(resourceText);var mana=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};for(int n=0;n<10;n++){var mark=new Border{Width=minimal?5:7,Height=minimal?5:7,Margin=new Thickness(1,0,0,0),Background=n<p.Mana?B("#B5C8BB"):B("#FFFFFF"),BorderBrush=n<p.MaxMana?B("#A5B9AC"):Line,BorderThickness=new Thickness(1)};mana.Children.Add(mark);}Grid.SetColumn(mana,1);resources.Children.Add(mana);Put(grid,resources,1);return grid;}
