  for(int n=0;n<7;n++){int place=n;var border=new Border{Height=minimal?51:84,VerticalAlignment=VerticalAlignment.Top,Background=B("#FFFFFF"),BorderBrush=Line,BorderThickness=new Thickness(1),Margin=new Thickness(0,0,n==6?0:2,0),CornerRadius=new CornerRadius(codex?3:0),Cursor=Cursors.Hand};Grid.SetColumn(border,n);strip.Children.Add(border);if(n>=board.Count){border.Background=B("#FAFBFC");border.MouseLeftButtonDown+=(s,e)=>ClickEmptySlot(seat,place);continue;}var unit=board[n];liveUnits.Add(border);border.Tag=unit.Id;RegisterVisualTarget(seat,unit.Id,border);
