 }
 TextBlock ColoredUnitTags(BattleUnit unit){var text=T("",9,Muted);var tags=UnitTags(unit).Split(' ');for(int i=0;i<tags.Length;i++){if(i>0)text.Inlines.Add(new Run(" "));var run=new Run(tags[i]);if(fullEffects&&!minimal&&match.IsEnraged(unit)&&(tags[i]=="激怒"||tags[i]=="激"))run.Foreground=B(codex&&dark?"#D78B86":"#B04B46");text.Inlines.Add(run);}return text;}
 string UnitTags(BattleUnit unit){var tags=new List<string>();if(unit.Frozen)tags.Add("冻结");if(unit.Taunt)tags.Add("嘲讽");if(unit.Shield)tags.Add("圣盾");if(match.HasWindfury(unit))tags.Add("风怒");if(match.IsEnraged(unit))tags.Add("激怒");if(unit.Charge)tags.Add("冲锋");if(unit.Poison)tags.Add("剧毒");if(unit.Stealth)tags.Add("潜行");var card=match.Card(unit.CardId);if(!unit.Silenced){if(MatchEngine.Has(card,"DEATHRATTLE"))tags.Add("亡语");if(MatchEngine.Has(card,"ELUSIVE"))tags.Add("扰魔");if(MatchEngine.Has(card,"AURA"))tags.Add("光环");if(MatchEngine.Has(card,"CANT_ATTACK"))tags.Add("禁攻");if(card.BaseId=="CS2_033")tags.Add("冻伤");if(card.BaseId=="NEW1_009")tags.Add("治疗");}if(unit.SpellDamage>0)tags.Add((minimal?"法":"法强+")+unit.SpellDamage);if(minimal&&tags.Count>3)tags=tags.Select(t=>t=="光环"?"环":t.StartsWith("法")?"法"+unit.SpellDamage:t=="冻伤"?"寒":t=="治疗"?"愈":t.Substring(0,1)).ToList();return tags.Count==0?"—":String.Join(" ",tags);}
 FrameworkElement LiveHand(){var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(11)});grid.RowDefinitions.Add(new RowDefinition());var p=match.Players[matchViewSeat];grid.Children.Add(T("手牌 "+p.Hand.Count+" · 牌库 "+p.Deck.Count,9,Muted));var cards=new StackPanel{Orientation=Orientation.Horizontal};var scroll=new ScrollViewer{Content=cards,HorizontalScrollBarVisibility=ScrollBarVisibility.Hidden,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled};liveHandScroll=scroll;double restore=matchHandScroll;scroll.Loaded+=(s,e)=>scroll.ScrollToHorizontalOffset(restore);scroll.ScrollChanged+=(s,e)=>{if(e.HorizontalChange!=0)matchHandScroll=scroll.HorizontalOffset;};scroll.PreviewMouseWheel+=(s,e)=>{if(scroll.ScrollableWidth>0){scroll.ScrollToHorizontalOffset(scroll.HorizontalOffset-e.Delta);e.Handled=true;}};Put(grid,scroll,1);
  foreach(var hand in p.Hand){var card=match.Card(hand.CardId);var inner=new Grid();inner.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(13)});inner.ColumnDefinitions.Add(new ColumnDefinition());inner.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(12)});var cost=T(card.Cost.ToString(),10,Muted);cost.TextAlignment=TextAlignment.Center;inner.Children.Add(cost);var title=T(minimal?(card.Type=="SPELL"?"法":card.Type=="WEAPON"?"武":"随"):card.Name,10,Ink);title.TextTrimming=TextTrimming.CharacterEllipsis;Grid.SetColumn(title,1);inner.Children.Add(title);var dot=Btn("⋯",12);dot.Height=19;dot.FontSize=9;dot.Padding=new Thickness(0);dot.Click+=(s,e)=>InspectMatchCard(card);Grid.SetColumn(dot,2);inner.Children.Add(dot);var border=new Border{Child=inner,Width=minimal?57:105,Height=22,Background=pending=="play"&&pendingId==hand.Id?B("#EDF4F0"):B("#FFFFFF"),BorderBrush=Line,BorderThickness=new Thickness(1),Margin=new Thickness(0,0,3,0),Cursor=Cursors.Hand};border.MouseLeftButtonDown+=(s,e)=>BeginCard(hand.Id);cards.Children.Add(border);}return grid;
 }
 FrameworkElement LiveInspection(){var stack=new StackPanel{Margin=new Thickness(4,0,4,0)};var header=new Grid{Height=13};header.ColumnDefinitions.Add(new ColumnDefinition());header.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(60)});var title=T(inspectedCard.Name,10,Ink);title.TextTrimming=TextTrimming.CharacterEllipsis;header.Children.Add(title);var back=Btn("返回手牌",60);back.HorizontalAlignment=HorizontalAlignment.Right;back.Height=13;back.FontSize=9;back.Click+=(s,e)=>{inspectMatch=false;RenderMatch();};Grid.SetColumn(back,1);header.Children.Add(back);stack.Children.Add(header);var text=T(CardDetailMetadata(inspectedCard)+Environment.NewLine+(inspectedCard.Text.Length>0?inspectedCard.Text:"无特殊效果。"),9,Muted);text.TextWrapping=TextWrapping.Wrap;stack.Children.Add(text);return new Border{Background=B("#F7F8FA"),BorderBrush=Line,BorderThickness=new Thickness(1),Child=new ScrollViewer{Content=stack,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}};}
 void InspectMatchCard(CardRecord card){inspectedCard=card;inspectMatch=true;RenderMatch();}
 void BeginCard(int handId){if(!CanMatchInput())return;var hand=match.Players[matchViewSeat].Hand.First(h=>h.Id==handId);var card=match.Card(hand.CardId);if(!match.Rules.Supports(card)){status.Text="该卡效果尚未实现。";return;}if(match.Players[matchViewSeat].Mana<card.Cost){status.Text="法力不足。";return;}if(card.Type=="MINION"&&match.Players[matchViewSeat].Board.Count>=7){status.Text="战场已满七个随从。";return;}pending="play";pendingId=handId;pendingPosition=-1;inspectMatch=false;var effect=match.Rules.Effect(card);if(card.Type!="MINION"&&effect.Target=="NONE")DoMatch("play",handId);else RenderMatch();}
 void ClickEmptySlot(int seat,int position){if(!CanMatchInput()||pending!="play"||seat!=matchViewSeat)return;var hand=match.Players[seat].Hand.FirstOrDefault(h=>h.Id==pendingId);if(hand==null)return;var card=match.Card(hand.CardId);if(card.Type!="MINION")return;pendingPosition=Math.Min(position,match.Players[seat].Board.Count);var effect=match.Rules.Effect(card);if(effect.Target=="NONE"||!match.HasTargets(seat,effect.Target,false))DoMatch("play",pendingId,null,pendingPosition);else RenderMatch();}
 void ClickMatchTarget(MatchTarget target){if(!CanMatchInput())return;
  if(pending=="play"){var hand=match.Players[matchViewSeat].Hand.FirstOrDefault(h=>h.Id==pendingId);if(hand==null){ClearPending();RenderMatch();return;}var card=match.Card(hand.CardId);if(NeedsPlacement()){status.Text="先点击己方随从下方的左 / 右，或点击空槽。";return;}if(match.Rules.Effect(card).Target=="NONE"){status.Text="请选择己方空槽召唤随从。";return;}DoMatch("play",pendingId,target,pendingPosition);return;}
  if(pending=="power"){DoMatch("power",0,target);return;}
  if((pending=="attack"||pending=="heroattack")&&target.Seat!=matchViewSeat){DoMatch("attack",pending=="heroattack"?0:pendingId,target);return;}
  if((pending=="attack"||pending=="heroattack")&&target.Seat==matchViewSeat&&target.Hero){BeginHeroAttack();return;}
  if(target.Seat==matchViewSeat&&!target.Hero){var unit=match.Unit(target);string error=match.CanAttack(matchViewSeat,unit);if(error!=null){status.Text=error;return;}pending=pending=="attack"&&pendingId==target.UnitId?"":"attack";pendingId=target.UnitId;inspectMatch=false;RenderMatch();}else status.Text="先点击己方随从或手牌。";
 }
 void BeginHeroAttack(){if(!CanMatchInput())return;string error=match.CanHeroAttack(matchViewSeat);if(error!=null){status.Text=error;return;}pending="heroattack";pendingId=0;inspectMatch=false;RenderMatch();}
 void BeginPower(){if(!CanMatchInput())return;var player=match.Players[matchViewSeat];if(player.PowerUsed){status.Text="本回合已使用英雄技能。";return;}if(player.Mana<2){status.Text="英雄技能需要两点法力。";return;}if(match.PowerNeedsTarget(matchViewSeat)){pending="power";inspectMatch=false;RenderMatch();}else DoMatch("power");}
 void ApplyMatchAction(ActionResult result){if(result.Success){ClearPending();inspectMatch=false;testTakeOpen=false;RenderMatch();Record(match.Log.LastOrDefault()??"操作完成");}status.Text=result.Message;}
 void ShowMatchResult(ActionResult result){status.Text=result.Message;}
 void ShowHandoff(){var cover=new Border{Background=B("#FFFFFF"),BorderBrush=Line,BorderThickness=new Thickness(1),Margin=new Thickness(12,18,12,18)};Grid.SetRow(cover,1);Grid.SetRowSpan(cover,6);var stack=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};stack.Children.Add(T("轮到玩家 "+(match.Active+1),12,Ink));var button=Btn("继续",80);button.Margin=new Thickness(0,12,0,0);button.Click+=(s,e)=>{awaitHandoff=false;matchViewSeat=match.Active;matchHandScroll=0;ClearPending();RenderMatch();};stack.Children.Add(button);cover.Child=stack;livePanel.Children.Add(cover);}
}
